function FightBonusNew:SortData()
    for i = 1, #self.rewardData do
        for j = 1, #self.rewardData do
            local is1Get = false
            local is2Get = false

            --三星
            if self.rewardData[i] == Constants.QuestRewardType.StarRewardId then
                is1Get = QuestConfMgr:GetInstance():IsCompleteAllCondition(self.levelId)
            --首通
            elseif self.rewardData[i] == Constants.QuestRewardType.FristRewards then
                if self._curLevelType == Constants.IDType.QuestSeniorEquipCopy then
                    local equipQuestComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.EquipQuestComponent)
                    is1Get = equipQuestComp:IsPassQuestById(equipQuestComp:GetCurSeniorQuestId())
                else
                    is1Get = QuestConfMgr:GetInstance():IsPassQuest(self.levelId)
                end
            end 

            --三星
            if self.rewardData[j] == Constants.QuestRewardType.StarRewardId then
                is2Get = QuestConfMgr:GetInstance():IsCompleteAllCondition(self.levelId)
            --首通
            elseif self.rewardData[j] == Constants.QuestRewardType.FristRewards then
                if self._curLevelType == Constants.IDType.QuestSeniorEquipCopy then
                    local equipQuestComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.EquipQuestComponent)
                    is2Get = equipQuestComp:IsPassQuestById(equipQuestComp:GetCurSeniorQuestId())
                else
                    is2Get = QuestConfMgr:GetInstance():IsPassQuest(self.levelId)
                end
            end 

            local isChange = false
            if is2Get and (not is1Get) then
                isChange = true
            else
                isChange = j < i
            end

            if isChange then
                local t = self.rewardData[i]
                self.rewardData[i] = self.rewardData[j]
                self.rewardData[j] = t
            end
        end
    end
end 

function FightBonusNew:FillRewards()
    local count = 0
    for i = 1, #self.rewardData do
        local type = self.rewardData[i]

        local rewardData = RewardConfMgr:GetQuestRewardData(self.levelId, type)
        if rewardData and #rewardData > 0 then
            local cell = CfUtils.InstantiateGo(self.cell, self.cont)
            local scr = CfUtils.GetLuaScr(cell, FightBonusCellNode)
            if scr then
                scr:Refresh(rewardData, i, self.levelId, type)
                scr:PlayAni(count)
                count = count + 1
            end
        end
    end
end

